// Поиск виновника по регрессу без пересборки: файл `bisect` рядом с EBOOT (число hex, например 3ff) включает ПРЕЖНИЕ пути вместо оптимизаций дня; нет файла — как обычно.
// Бит: 0 запекание пропов B1 (PROP_BAKE_OLD), 1 гибрид листов клеток (CELL_HYB_OLD), 2 дальность по перегрузке (DD_ADAPT_OLD), 3 повтор отсечения B8 (CULL_REUSE_OLD),
//      4 отложенная поза далёких стейтпропов (SP_POSE_LOD_OLD), 5 ближний проход (NEARPASS_OLD), 6 (зарезервирован), 7 PVS по курсу (PVS_SECTOR_OLD),
//      8 быстрый спуск дальности (DD_FAST_OLD), 9 брифинг без перерисовки мира (BRIEF_FREEZE_OLD), 10 регулятор дальности по среднему без отклонения (DD_SIGMA_OLD), 11 без прогрева листов клеток под брифингом (BRIEF_WARM_OLD), 12 без перегруппировки полупрозрачного (TQ_FAST_OLD), 13 нестабильная сортировка полупрозрачного (TQ_STABLE_OLD), 14 без прогрева на хвосте экрана загрузки (LOAD_WARM_OLD). Макросы -D...=1 при сборке по-прежнему главнее файла.
// Файл читается при запуске (main_loop.h), в релизной сборке служебные файлы недоступны (sibling), значит маска всегда 0.
#ifndef SHAR_BISECT_H
#define SHAR_BISECT_H
static unsigned bisOld;
#define BIS(b) ((bisOld >> (b)) & 1u)
#endif
